import "package:flutter/material.dart";
import "package:provider/provider.dart";
import "../../providers/auth_provider.dart";
class SiswaPengaturanNew extends StatelessWidget { const SiswaPengaturanNew({super.key}); @override Widget build(BuildContext context) => Scaffold(backgroundColor: const Color(0xFFF8FAFC), appBar: AppBar(title: const Text("Pengaturan"), backgroundColor: Colors.white, elevation:0), body: ListView(padding: const EdgeInsets.all(16), children: [Card(child: ListTile(leading: const Icon(Icons.person_outline), title: Text(context.watch<AuthProvider>().user?.name ?? "-"), subtitle: Text(context.watch<AuthProvider>().user?.email ?? ""))), const SizedBox(height:12), Card(child: ListTile(leading: const Icon(Icons.logout, color: Colors.red), title: const Text("Keluar"), onTap: ()=> context.read<AuthProvider>().signOut()))])); }
